import math
def priority(task, state, k=0.5, alpha=1.0, b=0.5, q=0.25,
             m_prem=1.5, m_var=1.0, m_sv=1.0, c=0.5):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    now = state.now
    finish = now + est
    decay_end = task.due + 2.0 * est
    if finish >= decay_end:
        return 0.0
    slack = max(0.0, task.due - est - now)
    if finish > task.due:
        remaining = max(0.0, 1.0 - (finish - task.due) / (2.0 * est))
        marginal = task.weight / (2.0 * est)
        base = marginal * (1.0 + alpha * remaining)
    else:
        base = task.weight * math.exp(-slack / max(k * est, 1e-6)) / est
    wait = max(0.0, now - task.release)
    aging = 1.0 + b * wait / est
    type_mult = 1.0
    if task.task_type == 'variant_calling':
        type_mult = m_var
    elif task.task_type == 'sv_calling':
        type_mult = m_sv
    tenant_mult = 1.0
    if task.tenant == 'premium':
        tenant_mult = m_prem
        if slack <= c * est:
            tenant_mult *= m_prem
    return tenant_mult * type_mult * base * aging / max(cores ** q, 1e-6)  # tuned (k=0.28,alpha=1.94,b=0.44,q=0.519,m_prem=2.29,m_var=0.363,m_sv=0.411,c=0.519)

def priority(task, state, m=2.0, a=0.5, k=1.0, w_pow=1.0):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    due = task.due
    tier = m if task.tenant == 'premium' else 1.0
    weight = max(task.weight, 1e-6) ** w_pow
    base = tier / est
    if now >= due + 2.0 * est:
        return 0.0
    wait = max(0.0, state.queue_work / max(state.capacity, 1e-6))
    slack = due - now - est
    deficit = max(0.0, k * wait - slack)
    if deficit <= 0.0:
        return base
    if now <= due:
        frac = 1.0
    else:
        frac = max(0.0, (due + 2.0 * est - now) / (2.0 * est))
    risk = deficit / (deficit + max(state.mean_est, 1e-6))
    return base + a * tier * weight * frac * risk / est  # tuned (m=1.02,a=0.447,k=1.44,w_pow=0.489)

def priority(task, state, c=1.0, a=0.0, b=0.0, ma=1.0, mv=1.0, ms=1.0):
    e = max(task.estimated_runtime, 1e-6)
    now = state.now
    wait = now - task.release
    ratio = wait / e
    cap = max(state.capacity, 1e-6)
    cong = state.queue_work / cap
    free_ratio = state.free / cap
    threshold = c * (1.0 + a * cong + b * (1.0 - free_ratio))
    type_mult = 1.0
    if task.task_type == 'alignment':
        type_mult = ma
    elif task.task_type == 'variant_calling':
        type_mult = mv
    elif task.task_type == 'sv_calling':
        type_mult = ms
    base = type_mult / e
    if ratio >= threshold:
        base += 1e6
    return base  # tuned (c=3.2,a=0,b=0,ma=0.325,mv=1.23,ms=0.832)

def priority(task, state, beta=1.0, m=1.0, penalty=1e3, gamma=0.5, rho=0.5, eps=1e-6):
    est = max(task.estimated_runtime, eps)
    tier = m if task.tenant == 'premium' else 1.0
    comp = state.now + est
    base = -max(task.due, comp)
    if comp <= task.due:
        rem = 1.0
    else:
        rem = max(0.0, 1.0 - (comp - task.due) / (2.0 * est))
    if rem <= 0.0:
        return base - penalty
    if state.free > eps:
        fit_ratio = min(task.resource_need, state.free) / state.free
    else:
        fit_ratio = 0.0
    pressure = state.queue_work / max(state.capacity, eps)
    res_factor = 1.0 / max(1.0 + rho * task.resource_need / max(state.capacity, eps), eps)
    return base + beta * task.weight * tier * rem * res_factor * (1.0 + gamma * fit_ratio * (1.0 + pressure)) / est

def priority(task, state, a=1.0, b=1.0, m=2.0):
    p = max(task.estimated_runtime, 1e-6)
    now = state.now
    slack = task.due - now - p
    if now >= task.due + 2.0 * p:
        return -1e9
    tier = m if task.tenant == 'premium' else 1.0
    if slack >= 0.0:
        return -slack + a * tier * task.weight / p
    else:
        remaining_frac = max(0.0, (task.due + 2.0 * p - now) / (2.0 * p))
        return b * tier * task.weight / p * remaining_frac

import math
def priority(task, state, k_align=0.5, k_variant=0.5, k_sv=0.5):
    now = state.now
    e = max(task.estimated_runtime, 1e-6)
    w = task.weight
    due = task.due
    mean_e = max(state.mean_est, 1e-6)
    t = task.task_type
    if t == 'alignment':
        k = k_align
    elif t == 'variant_calling':
        k = k_variant
    elif t == 'sv_calling':
        k = k_sv
    else:
        k = 0.5
    finish = now + e
    if finish <= due:
        slack = due - e - now
        return (w / e) * math.exp(-slack / (max(k, 1e-6) * mean_e))
    else:
        rem = max(0.0, 1.0 - (finish - due) / (2.0 * e))
        return (w / e) * rem  # tuned (k_align=0.694,k_variant=0.312,k_sv=0.255)

import math
def priority(task, state, k=0.5, alpha=1.0, beta=2.0):
    e = max(task.estimated_runtime, 1e-6)
    now = state.now
    due = task.due
    comp = now + alpha * e
    if comp <= due:
        f = 1.0
    elif comp >= due + 2.0 * e:
        f = 0.0
    else:
        f = 1.0 - (comp - due) / (2.0 * e)
    decay_factor = min(1.0, beta * f)
    if decay_factor <= 0.0:
        return 0.0
    slack = due - e - now
    slack = max(0.0, slack)
    mean = max(state.mean_est, 1e-6)
    return (task.weight / e) * decay_factor * math.exp(-slack / (max(k, 1e-6) * mean))

def priority(task, state, c=1.0, m=2.0, a=1.0, b=0.0, d=10.0, aging=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    proj = state.now + est
    base = -max(task.due, proj)
    tier = m if task.tenant == 'premium' else 1.0
    if proj <= task.due:
        rem = 1.0
    else:
        rem = max(0.0, 1.0 - (proj - task.due) / (2.0 * est))
    if rem <= 0.0:
        return base - d
    age = max(0.0, state.now - task.release)
    age_score = aging * age / max(est, 1e-6)
    return base + age_score + c * tier * task.weight * rem / (est**a * cores**b)  # tuned (c=2.51,m=1.08,a=0.407,b=0,d=24.3,aging=1.95)
